UPDATE sd_board_post
SET view_count = view_count + 1
WHERE post_id = #{postId}
  AND board_type_code = 'INQUIRY'
  AND deleted_yn = 'N'
  AND (
        visibility_status = 'PUBLIC'
        OR user_id = #{loginUserId}
  )

UPDATE sd_inquiry_detail
SET
    inquiry_category_code = #{inquiryCategoryCode},
    updated_at = CURRENT_TIMESTAMP
WHERE post_id = #{postId}
  AND EXISTS (
      SELECT 1
      FROM sd_board_post bp
      WHERE bp.post_id = #{postId}
        AND bp.user_id = #{userId}
        AND bp.board_type_code = 'INQUIRY'
        AND bp.deleted_yn = 'N'
  )
